package com.ccb.datamigration.service;
import com.ccb.common.exception.*; import java.util.*; import org.springframework.stereotype.Repository;
@Repository public class MeetingRepository { private final MeetingMapper mapper; public MeetingRepository(MeetingMapper mapper){this.mapper=mapper;} public long count(Map<String,Object> p){Long n=mapper.count(p);return n==null?0:n;} public List<Map<String,Object>> list(Map<String,Object> p){return mapper.list(p);} public Map<String,Object> require(long t,long id){return one(mapper.find(t,id),"会议纪要不存在");} public Map<String,Object> requireDeleted(long t,long id){return one(mapper.findDeleted(t,id),"会议纪要不存在");} public void insert(Map<String,Object> p){mapper.insert(p);} public int update(Map<String,Object> p){return mapper.update(p);} public int delete(long t,long id,long actor){return mapper.softDelete(t,id,actor);} public int restore(long t,long id,long actor){return mapper.restore(t,id,actor);} public int purge(long t,long id){mapper.deleteIssues(t,id);mapper.deleteSystems(t,id);return mapper.purge(t,id);} public List<Long> deletedIds(long t,long project){return mapper.deletedIds(t,project);} public void purgeDeletedProject(long t,long project){mapper.deleteProjectIssues(t,project);mapper.deleteProjectSystems(t,project);mapper.purgeDeletedProject(t,project);} public List<Map<String,Object>> issueOptions(long t,long project){return mapper.issueOptions(t,project);} public void replaceSystems(long t,long id,long project,List<String> codes,long actor){mapper.deleteSystems(t,id);for(String code:codes){Map<String,Object> p=new LinkedHashMap<>();p.put("id",System.currentTimeMillis()*1000+new Random().nextInt(1000));p.put("tenantId",t);p.put("meetingId",id);p.put("projectId",project);p.put("systemCode",code);p.put("actorId",actor);mapper.insertSystem(p);}} public void replaceIssues(long t,long id,List<Long> ids,long actor){mapper.deleteIssues(t,id);for(Long issue:ids){Map<String,Object> p=new LinkedHashMap<>();p.put("id",System.currentTimeMillis()*1000+new Random().nextInt(1000));p.put("tenantId",t);p.put("meetingId",id);p.put("issueId",issue);p.put("actorId",actor);mapper.insertIssue(p);}} public boolean issue(long t,long project,long id){Integer n=mapper.issueCount(t,project,id);return n!=null&&n>0;} public boolean system(long t,long project,String code){Integer n=mapper.systemCount(t,project,code);return n!=null&&n>0;} public boolean code(Map<String,Object> p){Integer n=mapper.codeCount(p);return n!=null&&n>0;} public int restoreAttachment(long t,long id,long attachment){return mapper.restoreAttachment(t,id,attachment);} public long deletedAttachmentCount(Map<String,Object> p){Long n=mapper.countDeletedAttachments(p);return n==null?0:n;} public List<Map<String,Object>> deletedAttachments(Map<String,Object> p){return mapper.deletedAttachments(p);} public List<Long> deletedAttachmentRows(long t,long project){return mapper.deletedAttachmentRows(t,project);} public long project(long t,long id){List<Long> ids=mapper.projectIds(t,id);if(ids.isEmpty())throw new BusinessException(ErrorCode.BAD_REQUEST,"会议纪要不存在");return ids.get(0);} public void audit(long t,long actor,long project,String op,long id){mapper.insertAudit(t,actor,project,op,id);} private Map<String,Object> one(List<Map<String,Object>> r,String msg){if(r.isEmpty())throw new BusinessException(ErrorCode.BAD_REQUEST,msg);return r.get(0);} }
